<?php
$search=query_input('search'); $status=query_input('status'); $document=query_input('document');
$where=[]; $params=[]; $invalid=false;
if (isset($_GET['search'])) {
    if (!valid_text($search,150)) $invalid=true;
    else { $where[]="(CONCAT(u.first_name,' ',u.last_name) LIKE ? OR r.id=?)"; $params[]='%'.$search.'%'; $params[]=preg_match('/^(?:REQ-)?(\d+)$/iD',$search,$m)?(int)$m[1]:0; }
}
if ($status!=='') { if (!in_array($status,REQUEST_STATUSES,true)) $invalid=true; else { $where[]=$status==='Submitted'?"r.status IN ('Pending','Submitted')":'r.status=?'; if($status!=='Submitted') $params[]=$status; } }
if ($document!=='') { if (!ctype_digit($document)) $invalid=true; else { $where[]='r.document_id=?'; $params[]=(int)$document; } }
$requests=$invalid?[]:request_rows($params,$where?'WHERE '.implode(' AND ',$where):'');
?>
<div class="section-title"><h2>All requests</h2><button class="button secondary" type="button" data-reveal="track-request">Track Request</button></div>
<form method="get" class="panel filters"><input type="hidden" name="page" value="requests"><div id="track-request" <?= isset($_GET['search'])?'':'hidden' ?>><label>Resident name or request ID<input name="search" value="<?= e($search) ?>" maxlength="150" placeholder="Name or REQ-000001" <?= isset($_GET['search'])?'':'disabled' ?>></label><button class="button primary">Search</button></div><label>Document<select name="document"><option value="">All Documents</option><?php foreach(rows('SELECT id,name FROM documents ORDER BY name') as $doc): ?><option value="<?= (int)$doc['id'] ?>" <?= $document===(string)$doc['id']?'selected':'' ?>><?= e($doc['name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">All Status</option><?php options(REQUEST_STATUSES,$status); ?></select></label><button class="button secondary">Apply filters</button><a href="index.php?page=requests">Reset</a></form>
<?php if($invalid): ?><dialog data-auto-open><h2>Invalid</h2><p>Enter a valid name, request ID, or filter.</p><a class="button primary" href="index.php?page=requests">OK</a></dialog><?php endif; ?>
<section class="panel table-scroll"><table><thead><tr><th>Request ID</th><th>Resident</th><th>Document</th><th>Status</th><th>Payment</th><th>Submitted</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= e(request_id((int)$r['id'])) ?></td><td><?= e($r['resident_name']) ?></td><td><?= e($r['document_name']) ?></td><td><span class="badge"><?= e(status_label($r['status'])) ?></span></td><td><?= e($r['payment_status']) ?></td><td><?= e($r['created_at']) ?></td><td><a class="button secondary compact" href="index.php?page=requests&open=<?= (int)$r['id'] ?>">Manage</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$requests): ?><p class="empty">No record found</p><?php endif; ?></section>
<?php
$open=query_input('open');
$r=ctype_digit($open)?(request_rows([(int)$open],'WHERE r.id=?')[0]??null):null;
if($r): ?>
<section class="panel dashboard-actions"><div class="section-title"><h2><?= e(request_id((int)$r['id']).' · '.$r['resident_name']) ?></h2><a class="button secondary" href="index.php?page=editor&id=<?= (int)$r['id'] ?>">Continue and edit the document</a></div><p><?= e($r['document_name']) ?></p><dl class="summary-details"><dt>Purpose</dt><dd><?= nl2br(e($r['purpose'])) ?></dd><dt>Additional information</dt><dd><?= nl2br(e($r['additional_information'])) ?></dd><dt>Review reason</dt><dd><?= e($r['review_reason']?:'None') ?></dd></dl>
<?php action_form('review',(int)$r['id']); ?><div class="form-grid"><label>Review decision<select name="status"><?php options(['Approved','Rejected'],$r['status']); ?></select></label><label>Reason (optional)<textarea name="reason" maxlength="3000"><?= e($r['review_reason']) ?></textarea></label></div><button class="button secondary">Review</button></form>
<hr><?php action_form('update_request',(int)$r['id']); ?><div class="form-grid"><label>Status<select name="status"><?php options(REQUEST_STATUSES,status_label($r['status'])); ?></select></label><label>Payment status<select name="payment_status"><?php options(['Paid','Not Paid'],$r['payment_status']); ?></select></label><label>Payment amount (PHP)<input name="payment_amount" type="number" min="0" max="99999999.99" step="0.01" required value="<?= e($r['payment_amount']) ?>"></label><label>Processing options<select name="processing"><?php options(['','Processing','Cancel'],''); ?></select></label><?php foreach(['pickup_date'=>'Pickup date & time','processing_date'=>'Processing date & time'] as $field=>$label): ?><label><?= e($label) ?><input type="datetime-local" name="<?= e($field) ?>" value="<?= $r[$field]?e(date('Y-m-d\TH:i',strtotime($r[$field]))):'' ?>"></label><?php endforeach; ?><label>Pickup<select name="pickup_option"><?php options(['Pick up','Not needed'],$r['pickup_option']); ?></select></label><label>Delivery<select name="delivery_option"><?php options(['Delivery','Not needed'],$r['delivery_option']); ?></select></label></div><button class="button primary">Save Status Update</button></form></section>
<?php endif; ?>
